import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷二十六","description":"周易经传集解 - 周易经传集解卷二十六","frontmatter":{"title":"周易经传集解卷二十六","description":"周易经传集解 - 周易经传集解卷二十六"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/027.md","filePath":"zh/classics/jingchuan-jijie/027.md"}'),r={name:"zh/classics/jingchuan-jijie/027.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷二十六",tabindex:"-1"},[n("周易经传集解卷二十六 "),e("a",{class:"header-anchor",href:"#周易经传集解卷二十六","aria-label":"Permalink to “周易经传集解卷二十六”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解卷二十六 ​震坎艮震宋林栗撰。序：卦曰：「主器者莫若长子，故受之以震。」震者，动也。震之成卦，「鼎」之变也。自「鼎」之「震」变，下卦「巽」、上卦「离」而成也。巽，长女也；离，中女也；而震则长男也。夫器之大者莫若鼎，有是器，必有以主之。长女、中女，皆非主器者也。主之者，其惟长男乎？故夫革有冶铸之功，鼎有亨饪之用，非震则莫能受之矣。是故「鼎」之初六，特著其义曰：「得妾以其子，无咎。」而序则以「震」继之，明主器之重也。天下者，大器也。一人元良，万国以正。唐、虞禅，夏后、殷、周继，其此之谓乎？或曰：「唐、虞之禅，传诸人也，而取诸长子，何哉？」曰：易者，象也；象者，象此者也。谓之长子者，言其可以长人也。其子不足以长人，而天下之能长人者，莫如舜、禹，谓之长子，不亦可乎？震：亨。震来虩虩，笑言哑哑；震惊百里，不丧匕鬯。象曰：震，亨。「震来虩虩」，恐致福也。「笑言哑哑」，后有则也。「震惊百里」，惊远而惧迩也。出可以守宗庙社稷，以为祭主也。下震上震，成卦曰「震」者，初为「震」，二为「艮」，三为「坎」，四又为「震」，纯卦之义也，于「坎」、「离」辨之矣。艮，止也；「坎」，陷也。当震之时，止者皆动，陷者皆奋，是以谓之「震」也。震：亨。震来虩虩，笑言哑哑。震惊百里，不丧七鬯。何谓也？曰：「震」，动也，起也。为雷，为龙，为足，为长子，为东方之卦，皆亨之象也。而先儒训「震」为惧，以为恐惧以致亨，则失之矣。夫动起而谓之震者，取诸雷震以为义也。而震之为惧者，因其震惊而取之也。震在雷，惧在物，雷何惧之有哉？诗云：「薄言震之，莫不震叠」是也。今直训「震」为惧，而遂言恐惧以致亨，则是舍其主而议其宾矣。故「震」之诸爻，二阳，施震者也；其四阴，逼震者也。阳爻言「震」，为施震之义；阴爻言「震」，为遇震之辞，斯两得之矣。「震来虩虩，笑言哑哑」，为施震者言之也，初九是也。「震惊百里，不丧七鬯」，为遇震者言之也，六五是也。二阳莫善于初九，四阴莫善于六五，故彖发明之。诸家解此卦，惟苏氏得之。其说曰：「震之为道，以威达德者也。故可试而不可遂。试则养而无穷，遂则玩而不明。初九，试而不遂者也。以虩虩之震，而继之以哑哑之笑，明其不常用也。惟其不常用，故二阳莫敢犯其锋，皆以遁避而后免也。」其所以震物者，非以害之，欲其恐而致福也。有则者，言其不遂也。此论甚当。而「不丧七鬯」，初无其说。七鬯者，祭祀之物也。七以荐牲而升俎，鬯以灌地而求神。夫临祭祀，事神祗，虽当平时，犹难于无失，况夫雷震之威，远及百里，孰不忘其故常，失其所守，而乃能周旋于七鬯之事，不为震惊所变者，言其定也。故六五之辞曰「亿无丧有事」。有事者，有事于上帝，有事于先王也。六五刚柔相济，而得乎中行，故能度缓急之宜，审彼己之𫝑，虽临大事，遭大变，可以奉宗庙、事神祗，而不丧其所守也。故子曰：震来虩虩，恐致福也；笑言哑哑，后有则也。震惊百里，惊远而惧迩也。不丧匕鬯，可以守宗庙社稷，以为祭主也。今本衍一「出」字，号「不丧匕鬯」，一自疑「出」字是「鬯」字之误耳。王弼曰：「威震百里，则可以不丧匕鬯。」此说非是。象曰：瀳雷，震，君子以恐惧修省。震为雷，重震为瀳雷。天下雷行，物与无妄。而君子以之「恐惧修省」者，诗所谓「敬天之怒，无敢戏豫」，论语所谓「迅雷风烈必变」是也。古者先雷三日，奋木铎以令兆民，曰：「雷将发声，有不戒其容止者，生子不备，必有凶灾。」然则恐惧修省者，吉凶与民同患之意也。杂卦曰：「震，起也。」「震」之为卦，以雷之瀳至而成。其在六爻，以「震」之先后为义。「起」犹初也。「震」之初来，物莫不作；及其瀳至，则玩之矣。传曰：「一鼓作气，再而衰，三而竭。」是故震也者，天地之始也。「震」之二阳，初九为「起」，九四为「瀳」。初九有「虩虩」之威，而九四有「遂泥」之困者，先后之殊也。六二「跻于九陵」，六三行而「无眚」者，以初九之「虩虩」也。六五以「往」为「厉」，上六以「征」为「凶」者，以九四之「遂泥」也。「震」之为起，斯其义欤！初九：震来虩虩，后笑言哑哑，吉。象曰：「震来虩虩」，恐致福也；「笑言哑哑」，后有则也。初九「震」以阳居刚，而在下卦之下，上无其应，而承于六二之「艮」，故曰：「震来虩虩，后笑言哑哑，吉。」蝇虎谓之「虩虩」之捕蝇，悤焉而至，「震」之来也似之。「哑哑」，喜笑之声也，物得其所，则「笑言哑哑」，既「震」之后似之。无虩虩之威，则物不知畏；无哑哑之笑，则物不知怀。此初九之「震」所以有取于圣人也。彖举其略，爻言其详，所以然者，初九正而不失其时故也。其震物也，初无害之之心，欲其恐而致福也。其既震也，「载笑载言」，此所以为有则也。说者乃以为恐惧处震，则能保其安裕。若尔，则「笑言哑哑」，义既尽矣，何必言后又系之以「吉」乎？六二，震来厉，亿丧贝，跻于九陵。勿逐，七日得。象曰：「震来厉」，乘刚也。六二，「艮」也，以阴居柔而在下卦之中，上无其应而乘初九之震，故曰「震来厉」。「厉」，危也。六二以至柔而乘至刚，当震之来，其危甚矣，故曰「亿丧贝，跻于九陵」。「亿」，度也；「跻」，升也；「贝」，资财也；「陵」，大阜也。二以阴居柔，故有「丧贝」之象。「艮」为山，故有「跻陵」之象。六二居中履正，度震之来，必丧其贝，故升高以避之。初九之「震」，警之而已，岂利其贝也哉？故曰：「勿逐，七日得。」以明初九之志不在于贝也，逐则遂丧之矣。「九陵」者，「艮」乘震之象；「七日」者，阴阳之一复也。圣人于阳爻明施震之方，于阴爻言遇震之道，示人著矣。故子曰：「震来厉，乘刚也。」六三，震苏苏，震行无眚。象曰：「震苏苏」，位不当也。六三上体为「坎」，下体为「艮」，以阴居刚而在下卦之上，连于初九而承于九四，二爻皆「震」也，故曰：「震苏苏，震行无眚」。两言「震」者，在初九、九四之间也。「苏」与「苏」同，死而复生者谓之「苏」。初九之来，二既避之，则三当其震，居不当位，体乎艮「坎」。「艮」，止也；「坎」，陷也。止而陷焉，不能以自出，而震有反生之象，是以谓之「苏苏」也。三止则遇初，行则遇四。初之「震虩虩」而不可犯，四之「震遂泥」而不足畏，是以六三行而「无眚」也。故子曰：「震苏苏，位不当也。」君子之所以行乎患难，威武不能屈者，当其位而已矣。九四：震遂泥。象曰：「震遂泥」，未光也。九四上体为「震」，下体亦为「震」，以阳居柔而在上卦之下，承于六五而乘乎六三，二爻皆「坎」，而三又「艮」也，故曰：「震遂泥。」「遂」字依荀本作「队」，音坠。「泥」，水土相渐也。「艮」为土，「坎」为水，故有队泥之象。九四不中，不当其位，震于既震之后，震之又震，可已而不已，陷于「坎」「艮」之中，是以谓之「队泥」也。夫震也者，天之威也。震于此而动于彼，发越而光明者，动静不失其时也。今也极其𫝑而反陷于泥，则失其所以为威矣。书曰：「德威惟畏，德明惟明。」有德之威，使民易避而难犯，怒之则惧，爱之则怀。若夫强暴之威，使民无所措手足，将以穷物而不知自穷。故六三行而「无眚」，六五亿而「无丧」，上六「有言」而「无咎」者，为其队泥而莫之畏也。故子曰：「震队泥，未光也。」「震」，东方也，未出乎「坎」，所以为未光欤？六五：震往来，厉。亿无丧，有事。象曰：「震往来厉」，危行也。其事在中，大无丧也。六五，「坎」也，以阴居刚而在上卦之中，下无其应，而乘九四之「震」，故曰：「震往来，厉。」初九之「震」，易避而难犯。为六二者，来则厉，往则安。九四之「震」，可已而不已，其志将有所利焉。为六五者，往而避之，则丧其贝；来而乘之，则逆其锋。往来皆厉，则不动而已矣。故曰：「亿无丧，有事。」六五之遇九四也，强弱足以相当，不若六二之遇初九，非其敌也。柔得尊位得中，而四为之难，度己之𫝑，力足以当之，而不至于有丧，则固其疆圉，靖其国家，以为民神之主，从容堂陛之间，洁其簠簋笾豆，奉其牺牲粢盛，以为宗庙社稷之荐，刚不至于犯难，柔不至于畏人，虽九四之强暴莫能加焉，此彖之所谓「可以为祭主」者也。故子曰：「震往来厉，危行也。其事在中，大无丧也。」危在于行，则在中为无丧矣。「师」之六三曰：「师或与尸，大无功也。」「大无功」云者，谓有丧也。此言「大无丧」者，谓有功也。不言有功者，待其自至耳。六五之于九四，其𫝑虽足以相当，然阴之不逮阳必矣。苟可无丧，安能有功？左传所谓「彼竭我盈，故克之」也。以逸待劳，以壮待老，以整待乱，其有功也，不亦宜乎？上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。象曰：「震索索」，中未得也；虽凶无咎，畏邻戒也。上六，「艮」也。以阴居柔，而在上卦之上，下无其应，而连于九四之「震」，故曰：「震索索，视矍矍，征凶。」「索索」，气不充也；「矍矍」，神不定也。「艮」为止，而当「震」之来，处非其位，不得乎中，故有「索索」、「矍矍」之象。然九四之「震」，不足以加于六五，其能以及上六乎？苟征以避之，则四将乘虚而取其具矣。故曰：「震不于其躬，于其邻，无咎。」「躬」，上六也；「邻」，六五也。「震」之来也，不于我而于邻，则征而避之者过矣。上见五之不动以无丧，往来而皆厉，则亦将静而待之，是以为「无咎」也，故曰：「婚媾有言。」八纯之卦，上下敌应，无相与之义。其所称「婚媾」者，于其本体而言之也。九四之于六五，有「婚媾」之道，而以其威加焉，故不之与。舍而求上六，上之与四，无相与之义，是以不免于「有言」也。夫六二、六五之于「震」为近，或亿无丧而有事，或亿有丧而避之，未尝至于颠沛而失据也。六三、上六皆远于「震」，而三至于「苏苏」，上至于「索索」者，谓其无主于中，遇物而自丧也。然初九以其威加于六三，行而避之，则可以「无眚」；而九四以其威加于上六，既不能胜而与之「婚媾」，犹不免于「有言」，明其「遂泥」而丧威之甚也。故子曰：「震索索，中未得也。」虽㓙无咎，畏邻戒也。序卦曰：「震者，动也。物不可以终动，止之，故受之以艮。艮者，止也。」「艮」之成卦，震之反也。自「震」之「艮」，二五不动，四爻则易而成也。一阳在二阴之下，居非其所，欲无动，得乎？是以谓之「震」也。一阳在二阴之上，动将何往？欲无止，得乎？是以谓之「艮」也。「艮」者万物之终，而「震」者万物之始也。震反则为「艮」，「艮」反则为「震」。是故「震」兼虩虩哑哑之辞，而「艮」备时止时行之义。「震」以初九为「吉」，而九四为「遂泥」；「艮」以上九为吉，而九三为「薰心」，明「震」之不可终动，「艮」之不可终止也。艮其背，不获其身；行其庭，不见其人，无咎。彖曰：「艮」，止也。时止则止，时行则行，动静不失其时，其道光明。「艮其止」，止其所也。上下相应，不相与也。是以下「获其身，行其庭，不见其人，无咎」也。下艮上「艮」。成卦曰「艮」者，初为艮，二为坎，三为震，四又为艮。「坎」，北方也；「震」，东方也。而「艮」则东北之卦，「坎」之所终，而「震」之所始也。「坎」不入乎「艮」，无以成万物之终；震不出乎「艮」，无以成万物之始。是故动以静为本，行以正为基。今夫草木之生，人见其条达茂遂而已，不知其枝干节叶已具于根荄脉缕之中。其本大者其末长，其源深者其流远，其积厚者其施博，自然之理也。故曰：「夫乾，其静也专，其动也直，是以大生焉。夫坤，其静也翕，其动也辟，是以广生焉。」然则当「艮」之时，苟不能止，无以为震动之资矣。易曰：「贞者，事之干也。」又曰「终万物始万物者，莫盛乎艮」。其此之谓欤？故子曰：「时止则止，时行则行，动静不失其时，其道光明。」日出乎震，则光明见矣。「艮其背，不获其身，行其庭，不见其人，无咎。」何谓也？曰：「艮」之三昼，一阳在二阴之外，其形内向，有背面而立之象。因而重之，则前「艮」为「背」，而后「艮」为止于其背之象矣。故「艮」之诸爻，上九止于九三之后，「艮其背」也。下无其应，不获其身也。庭，内外交际之地也。三四内外之交，庭之象也。九三为「震」，有反面外向之象，而动于群阴之中，是行其庭也。上无其应，是不见其人也。夫物近而不相得则凶，或害之，悔且吝。今也止于其背而不获其身，可谓近而不相得矣。不见其人而行其庭，可谓或害之者矣。然而系之旡咎者，何哉？「艮」之时则然也。夫「艮」也者，万物之所成终而所成始也。使上九「艮其背」而必获其身，则是与之偕止而不知行也。九三行其庭而不见其人，则是与之偕动而不知静也。故夫「艮」者，兼动静之宜，备屈伸之理。当上九之时，可止而不得不止也；当九三之时，可行而不得不行也。此所谓「其道光明」者欤？孟子有言：「可以仕则仕，可以止则止，孔子也。」或曰：「二体皆艮也，反而视之，则皆震也。何以知上九当止，而九三当行乎？」曰：上九者，「艮」之终也，万物归根复命之时也。万物归根复命，而一阳之气已动乎渊泉，则九三之象也。三之为震，出乎坎而不待反而后得之矣。故上九之辞曰：「敦艮吉。」九三之辞曰：「厉薰心。」明动静之各有其时也。君子之道，或出或处，或默或语，无适无莫，惟义所在，亦若是而已。孔子曰：「微子去之，箕子为之奴，比干谏而死，商有三仁焉。」夫比干已死，而箕子又为之奴，可谓「艮其背」矣，而不能止微子之勿行，是谓「不获其身」也。微子去商而归周，可谓行其庭矣，而不能使箕子之勿留，是谓不见其人也。三人之行不同，而夫子同称之曰「仁」，不敢少贬焉。夫有废必有兴，有终必有始。比干之死，与箕子之留，所以明君臣之义也；微子去之，所以明天人之归，存社稷之计也，其何咎之有哉？故子曰：「艮其背，止其所也。上下敌应，不相与也。是以不获其身，行其庭，不见其人，无咎也。」「艮其背」误作「艮其止」，当依上文读之。古者「背」「比」字通用，「比」字讹为「止」耳。背者，与人相违之地；北者，幽阴之所。当此而不止，则是失道而冥行也。夫八重卦皆敌应不相与，而独言于「艮」者，谓其以止为义，则无复相与之意矣。然则不获其身，不见其人，而可以咎之哉？书曰：「自靖，人自献于先王，我不顾行遁。」此之谓也。象曰：兼山，「艮」，君子以思不出其位。「艮」为山，重卦为兼山，但取山象，艮止之义备矣。而取诸「兼山」者，明尊卑小大各有其位，介辨而可不乱也。自天子至于庶人，守其位则安，出其位则悖，是以君子思而不出也。君止于仁，臣止于忠，父止于慈，子止于孝；上不逼下，下不僭上；尊者制其略，卑者治其详，皆不出其位之义也。杂卦曰：「艮，止也。」「艮」之为卦，以物之终始而成。其在六爻，以时止则止为义。今夫动者未尝无止，止者末尝无动，然天为动，地为止，何也？以其常者言之也。人受天地之中以生，参乎高厚之际，忽焉而动，倏焉而止，不可以一端而蔽之。欲言动静屈伸之理，莫若近取诸身矣。是以「艮」之为爻，分配人之一身。人之一身，动静之机，外系乎足，内系乎心。初六，「艮」也，足之位也；六四「艮」也，心之位也。心与足动，则身欲止不可得矣；心与足止，则身欲动不可得矣。然心止则足止矣，心止而足不止，则其动未可知也。故六四言「艮其身」，而初六但言「艮其趾」而已。易惟「咸」、「艮」二卦纯取于「身」，「咸」之诸爻，感应以相与，而「艮」之诸爻，敌应不相与，然皆可以取譬于身，何也？「咸」者，感也，感其心，然后能感人也。「艮」者，止也，止其心，然后能止其身也。是故以体分爻，然后有以见心之所在，心不可见，则「咸」、「艮」之义废矣。「咸」之九四，心之所在也，故曰「朋从尔思」。思者，心之用也。「艮」之六四，心之所在也，故曰「艮其身」。总言身者，心为之君也。「咸」之彖曰：「圣人感人心而天下和平。」「艮」之大象曰：「君子以思不出其征」。皆所以发明其义也。若夫六二之「艮其腓」，九三之「艮其限」，六五之「艮其辅」，皆取象于身，以明心之所在也。自趾而上之，至五为辅矣，则上之为颠可知也。不取诸「颠」而言「敦艮」者，微其显而阐其幽也。或曰：序卦「震动艮止也」，杂卦「震起艮止也」，二者之义有以异乎？曰：动止言其性也，起止言其时也。性也者，静躁之谓也；时也者，始终之谓也。要其归趣，则一而已。初六：艮其趾，无咎，利永贞。象曰：「艮其趾」，未失正也。初六，「艮」也，以阴居刚而在下卦之下，上无其应而承于六二之「坎」，故曰「艮其趾」。趾也者，体之至卑也。初居下而其数偶，故有趾之象焉。「艮其趾」则不行矣，又何咎之有哉？缺心而「艮其趾」，心苟欲动，非趾之能禁也，所谓系焉而止者欤？故曰：「利永贞。」贞犹固也，永以为贞，斯为善矣。子曰：「艮其趾」，末失正也。未之为言，不保其往云尔。「咸」言「拇」，「艮」言「趾」，象其物宜也。六二：艮其腓，不拯其随，其心不快。象曰：「不拯其随」，未退听也。六二，「坎」也，以阴居柔而在下卦之中，上无其应而承于九三之「震」，故曰「艮其腓」。「腓」，腨肉，下体之中也。二居中而数偶，故有腓之象焉。腓，块然无能为者也，不「艮其趾」而「艮其腓」，趾苟欲动，非腓之所能禁也。故曰：「不拯其随，其心不快。」「坎」为陷，故有「不拯」之象；为忧，为心病，故有「不快」之象。夫趾者，腓之所随也。「咸」之九三曰：「咸其股，执其随。」服之所随者，腓也，故「咸」之随为「腓」。「艮」六二：「艮其腓，不拯其随。」腓之所随者，趾也，故「艮」之随为「趾」。趾动而腓不能禁，趾陷而腓不能拯，其心安得而快乎？故子曰：「不拯其随，未退听也。」坎为耳，故有听象。六二止之不得其所，欲其退听，不亦难乎？九三：艮其限，列其夤，厉薰心。象曰：「艮其限」，危薰心也。九三上体为「震」，下体亦为「震」，以阳居刚而在下卦之上，上无其应，而介于六二、六四之间，二爻皆「坎」，而四又「艮」也，故曰「艮其限」。「限」，腰也，带之所限也。上下二体于此乎分，是以谓之限也。九三上下之交，其数奇，其体震，反复皆动，故有限之象焉。限也者，当吐纳呼吸之冲，系俯仰屈伸之节，而下可以形格𫝑禁者也。故「列其夤，厉薰心」。「列」字依盖本作「裂」。「裂」，绝也。「夤」，膂也。「薰」，蒸也。「裂其夤」者，其气勿乱而绝其膂也。「薰其心」者，其气郁蒸而病其心也。内不「艮其心」，外不「艮其趾」，而「艮」诸腰限之间，𫝑不能止，则将裂绝其膂而危病其心，非直不快而已。故子曰：「艮其限，危薰心也。」朱氏按，古本「薰」或作「动」，今两存之。「艮」之诸爻，惟九三不杂于柔，此彖之所谓「时行则行」者也。施「艮」于此，宜其危哉！六四，艮其身，无咎。象曰：「艮其身」，止诸躬也。六四上体为「艮」，下体为「坎」，以阴居柔，而在上卦之下，下无其应，而连于上九，乘乎九三，二爻皆「震」也，故曰「艮其身」。「身」也者，四肢百体之总名也。四肢百体合为一身，而听命于心。心也者，身之主也，虚其中而为之宰也。下三爻施「艮」于一体，犹不能禁，而此独能「艮其身」者，以心之所在故也。二言「不快」，三言「薰心」者，互发其辞也。四居上体之下，阴画为虚，故有「心」之象焉。「艮」为止，「震」为动，以静制动，是以谓之「艮其身」也。止之于心，则手足耳目无敢不听，夫何咎之有哉？故子曰：「艮其身，止诸躬也。」不言「身」而言「躬」者，身犹伸也，躬犹恭也。身之所恭，其当心之处乎？或曰：子以六四阴画虚，故有虚中之象。「咸」之九四则刚实为也，亦谓之心，何哉？曰：「咸」者，感也，心之动也；「艮」者，止也，心之静也。静则为虚，动则为实，圣人岂苟云乎哉？易曰：无思也，无为也，寂然不动，「艮」之心也。「感而遂通天下之故」，则「咸」之九四当之矣。六五：艮其辅，言有序，悔亡。象曰：「艮其辅」，以中正也。六五，「艮」也。以阴居刚，而在上卦之中，下无其应，而承上九之「震」，故曰「艮其辅」。「辅」，口车也，虚其中以为出纳者也。五居上卦之中，阴画为虚，故有「辅」之象焉。「咸」之「辅」在上，而「艮」之「辅」在五，则取其虚而已矣。辅也者，饮食之所自入，言语之所由出也。饮食以养其身，言语以道其意，未有能绝之者也。然则「艮其辅」云者，岂将缄塞之而已？平谨其言语，节其饮食，斯之谓「艮」矣。故曰：「言有序，悔亡」。时然后言，则不失其序，而悔可亡也。夫「艮」之言止也，以阴居刚，不纯乎静，是以有「悔」。动静语默，不失其时，是以「悔亡」也。故子曰：「艮其辅，以中正也。」以六居五，非「艮」之正，其以中为正者与？是故六四可以为心，而不可以为辅，六五可以为辅，而不可以为心，亦象其物宜也。体有动静，而心有不动者存，此四之所以「无咎」，而五之所以「悔七」者欤！上九：敦艮，吉。象曰：「敦艮」之「吉」，以厚终也。上九，「震」也。以阳居柔，而在上卦之上，下无其应，而乘六五之「艮」，故曰「敦艮」。敦，厚也，益也，艮之至也。「临」之上六，以益于六五，为「敦临」；「复」之六五，以益于六四，为「敦复」。今艮之上九，次乎六五，刚柔殊惟，而谓之「敦艮」，何也？曰：取诸重卦而系之，犹震之九四，因初九之震，而有遂泥之象也。九三既已艮矣，上九又从而益之，彖之所谓「艮其背，不获其身」者也。谓之「敦艮」，不亦宜乎？或曰：「子之言象，初六、六四艮也；九三、上九，震也。而易之，何哉？」曰：重卦六爻，无非艮也。初六、六四司艮之权，而所以艮者，九三、上九也。非艮乎阴，艮乎阳也。艮三索而得男，虽含震动之象，而当归根复命之时，止之又止，乃其所也，故曰「吉」。子曰：「敦艮之吉，以厚终也。」夫物不可以终动，亦不可以终止，故艮次震、「渐」、坎、「艮」，明屈信动静，犹寒暑之相推也。上九艮之终，终则变矣，而系之「敦艮」矣。夫子又继之以厚终之辞，何也？曰：震以初九为先，而九四为后。艮以上九为后，而九三为先。自下而上，自然之序也。然艮之先者，其震亦先，艮之后者，其震亦后，自然之理也。上九方「艮」而九三已震，则上之成终而三之成始也。「时止则止，时行则行」。方其止也，惟患其不固也；及其动也，惟患其不亟也。故止则如山，而动则如雷，易之道也。三在群阴之中，而上下皆「震」，其动也，孰能御之矣？上九之以厚终也，不亦善乎！周易经传集解卷二十六",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
